import{_ as i,C as a,o as n,c,j as t,a as o,E as r,w as l,ai as h}from"./chunks/framework.QGT6ovkH.js";const k=JSON.parse('{"title":"team-lead — The Orchestrator Agent","description":"","frontmatter":{},"headers":[],"relativePath":"agents/orion.md","filePath":"agents/orion.md"}'),p={name:"agents/orion.md"};function u(g,e,m,f,b,w){const d=a("WorkflowDiagram"),s=a("ClientOnly");return n(),c("div",null,[e[0]||(e[0]=t("div",{style:{display:"none"},hidden:"true","aria-hidden":"true","data-nosnippet":""},"Are you an LLM? You can read better optimized documentation at /opencode-team-lead/agents/orion.md for this page in Markdown format",-1)),e[1]||(e[1]=t("h1",{id:"team-lead-—-the-orchestrator-agent",tabindex:"-1"},[o("team-lead — The Orchestrator Agent "),t("a",{class:"header-anchor",href:"#team-lead-—-the-orchestrator-agent","aria-label":'Permalink to "team-lead — The Orchestrator Agent"'},"​")],-1)),e[2]||(e[2]=t("p",null,[t("code",null,"team-lead"),o(" is the central orchestrator injected by "),t("code",null,"opencode-team-lead"),o(". It is the only agent users interact with directly. It understands your request, breaks it into tasks, delegates everything to specialized sub-agents, validates results through the review cluster, and synthesizes a final report — without ever touching code directly.")],-1)),r(s,null,{default:l(()=>[r(d)]),_:1}),e[3]||(e[3]=h('<h2 id="the-cardinal-rule" tabindex="-1">The Cardinal Rule <a class="header-anchor" href="#the-cardinal-rule" aria-label="Permalink to &quot;The Cardinal Rule&quot;">​</a></h2><p><strong>The team-lead never does the work itself.</strong> Every technical action — analyzing code, editing files, running commands, searching codebases, reviewing security — is delegated to a specialized agent via the <code>task</code> tool.</p><blockquote><p>&quot;If you catch yourself about to use <code>edit</code>, <code>bash</code>, <code>glob</code>, <code>grep</code>, or <code>webfetch</code>: <strong>STOP</strong>. Delegate instead.&quot;</p></blockquote><p>The only exceptions:</p><ul><li><code>read</code> — to get the raw content of a file for coordination purposes (reading a plan, a config). For analysis or exploration of that content, delegate to <code>explore</code>.</li><li><code>bash</code> for a narrow set of git commands (<code>git status</code>, <code>git log</code>, <code>git add</code>, <code>git commit</code>, <code>git tag</code>, <code>git push</code>) and basic filesystem inspection (<code>ls</code>, <code>head</code>, <code>echo</code>) — because commit messages and deployment decisions require direct judgment.</li></ul><h2 id="what-the-team-lead-can-do" tabindex="-1">What the team-lead Can Do <a class="header-anchor" href="#what-the-team-lead-can-do" aria-label="Permalink to &quot;What the team-lead Can Do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>task</code></td><td>Delegate work to specialized agents — the team-lead&#39;s primary tool</td></tr><tr><td><code>todowrite</code></td><td>Track tasks and progress within a session</td></tr><tr><td><code>skill</code></td><td>Load skill instructions when a task requires them</td></tr><tr><td><code>read</code></td><td>Read raw file content directly for coordination (plans, configs)</td></tr><tr><td><code>question</code></td><td>Ask clarifying questions to the user</td></tr><tr><td><code>compress</code></td><td>Collapse closed conversation ranges to protect against context loss</td></tr><tr><td>Lifecycle tools</td><td><code>project_state</code>, <code>check_artifacts</code>, <code>mark_block_done</code>, <code>complete_plan</code>, <code>register_spec</code></td></tr></tbody></table><p>Everything else — exploration, editing, running tests, searching — goes to a sub-agent.</p><h2 id="lifecycle-tools" tabindex="-1">Lifecycle Tools <a class="header-anchor" href="#lifecycle-tools" aria-label="Permalink to &quot;Lifecycle Tools&quot;">​</a></h2><p>The team-lead has direct access to five bookkeeping tools. No delegation, no sub-agent, zero LLM overhead:</p><ul><li><strong><code>project_state()</code></strong> — Full view of exec-plans, specs, and briefs. Called at the start of every mission before any planning.</li><li><strong><code>check_artifacts()</code></strong> — Cross-artifact consistency scan (dead refs, stale statuses). Called at mission start and after completing each scope.</li><li><strong><code>mark_block_done(plan_file, block_name)</code></strong> — Check a block in an exec-plan after each validated delivery.</li><li><strong><code>complete_plan(plan_file)</code></strong> — Set an exec-plan to <code>status: completed</code> when all blocks are checked and the final review is APPROVED.</li><li><strong><code>register_spec(specFile, title)</code></strong> — Create a new spec file with minimal frontmatter. Never create spec files manually.</li></ul><p>See <a href="/opencode-team-lead/lifecycle-tools">Lifecycle Tools</a> for the full reference.</p><h2 id="_5-phase-workflow" tabindex="-1">5-Phase Workflow <a class="header-anchor" href="#_5-phase-workflow" aria-label="Permalink to &quot;5-Phase Workflow&quot;">​</a></h2><h3 id="_1-understand" tabindex="-1">1. Understand <a class="header-anchor" href="#_1-understand" aria-label="Permalink to &quot;1. Understand&quot;">​</a></h3><p>The team-lead starts by calling <code>project_state()</code> to load current exec-plans, specs, and briefs — this is how it recovers context after a session reset. It checks <code>todowrite</code> state to detect whether it is resuming a parked scope. Then it listens to the user request and asks clarifying questions if intent is ambiguous. Work does not start until the goal is understood.</p><h3 id="_2-plan" tabindex="-1">2. Plan <a class="header-anchor" href="#_2-plan" aria-label="Permalink to &quot;2. Plan&quot;">​</a></h3><p>The team-lead identifies which specialist agents are needed, determines task dependencies (what can run in parallel vs. sequentially), and creates a task list via <code>todowrite</code>. For complex or multi-session work it invokes the <code>planning</code> agent to write an exec-plan to disk. For simple, clear tasks, it produces an inline plan and proceeds directly.</p><h3 id="_3-delegate" tabindex="-1">3. Delegate <a class="header-anchor" href="#_3-delegate" aria-label="Permalink to &quot;3. Delegate&quot;">​</a></h3><p>The team-lead writes self-contained prompts for each agent — including all context that agent needs (file paths, constraints, prior decisions, expected output format). Independent tasks are launched in parallel. It updates <code>todowrite</code> after each delegation: <code>in_progress</code> before delegating, <code>completed</code> with a one-line result note when the agent returns.</p><h3 id="_4-review" tabindex="-1">4. Review <a class="header-anchor" href="#_4-review" aria-label="Permalink to &quot;4. Review&quot;">​</a></h3><p>Every code, architecture, infra, or security change is reviewed before reporting success. The team-lead always delegates to <code>review-manager</code> — never spawns reviewers directly. The review-manager selects the right specialists, runs them in parallel, synthesizes their verdicts, and returns a single structured result. See <a href="#review-protocol">Review Protocol</a> below.</p><h3 id="_5-synthesize-report" tabindex="-1">5. Synthesize &amp; Report <a class="header-anchor" href="#_5-synthesize-report" aria-label="Permalink to &quot;5. Synthesize &amp; Report&quot;">​</a></h3><p>The team-lead runs a self-evaluation before reporting — verifying the result fully answers the original request, that multi-agent outputs are coherent (no contradictions, no scope drift), and that nothing nags about correctness or side effects. Then it marks remaining <code>todowrite</code> tasks completed and reports to the user: outcome first, then issues and proposed next steps.</p><h2 id="review-protocol" tabindex="-1">Review Protocol <a class="header-anchor" href="#review-protocol" aria-label="Permalink to &quot;Review Protocol&quot;">​</a></h2><p>Every code, architecture, infra, or security change goes through <code>review-manager</code>. The protocol:</p><ol><li>The team-lead delegates to <code>review-manager</code> with: what changed, which files, the original requirements, and trade-offs made.</li><li><code>review-manager</code> selects reviewers, spawns them in parallel, arbitrates disagreements, and returns a structured verdict.</li><li>The team-lead acts on the verdict:</li></ol><table tabindex="0"><thead><tr><th>Verdict</th><th>Action</th></tr></thead><tbody><tr><td><strong>APPROVED</strong></td><td>Proceed to Synthesize &amp; Report</td></tr><tr><td><strong>CHANGES_REQUESTED</strong></td><td>Re-delegate fixes to the original producer with review-manager&#39;s feedback, then request a second review</td></tr><tr><td><strong>BLOCKED</strong></td><td>Stop. Escalate to the user with the full reasoning. Do NOT attempt to fix a BLOCKED issue without user input.</td></tr></tbody></table><p><strong>Maximum 2 review rounds.</strong> If still not approved after 2 iterations, escalate to the user.</p><p><strong>Skipping review</strong> is allowed only when all three are true: the change is documentation-only, has no security implications, and the user explicitly requested speed over thoroughness. When skipping, note it in the report.</p><h2 id="bug-finder-protocol" tabindex="-1">Bug-Finder Protocol <a class="header-anchor" href="#bug-finder-protocol" aria-label="Permalink to &quot;Bug-Finder Protocol&quot;">​</a></h2><p>When the user reports a bug — unexpected behavior, regression, crash, &quot;something stopped working&quot; — the team-lead <strong>always delegates to <code>bug-finder</code> first</strong>. Never to a general agent directly.</p><p><code>bug-finder</code> forces four fundamental questions before any fix is proposed:</p><ol><li>What is the exact problem? (symptom vs. root cause)</li><li>Where is the source of truth? (which code owns the broken behavior)</li><li>What alternatives were considered?</li><li>Why is this specific fix the right one?</li></ol><p><strong>When to skip <code>bug-finder</code>:</strong> only when the bug is trivially locatable (user points to the exact broken line with a clear typo) AND the fix is isolated with no risk of divergence.</p><table tabindex="0"><thead><tr><th><code>bug-finder</code> certainty</th><th>team-lead&#39;s action</th></tr></thead><tbody><tr><td><code>HIGH</code></td><td>Proceed to implementation via <code>general</code> agent with the analysis</td></tr><tr><td><code>MEDIUM</code></td><td>Proceed but flag the uncertainty in the user report</td></tr><tr><td><code>UNCERTAINTY_EXPOSED</code></td><td>Surface the open questions to the user before any fix</td></tr></tbody></table><h2 id="context-management" tabindex="-1">Context Management <a class="header-anchor" href="#context-management" aria-label="Permalink to &quot;Context Management&quot;">​</a></h2><p>The team-lead&#39;s context window is its most valuable resource. After every agent returns a result:</p><ol><li><strong>Update <code>todowrite</code></strong> — mark status and attach a one-line result note.</li><li><strong>Distill</strong> — if the agent&#39;s output contains technical details needed later (file paths, function signatures, decisions), distill to a compact summary. The distilled version should be a complete substitute for the raw output.</li><li><strong>Prune</strong> — once extracted, prune the raw agent output. Use <code>compress</code> on closed conversation ranges so they&#39;re protected against compaction without cluttering active context.</li></ol><p><code>compress</code> is what protects against compaction. There is no working-memory file that survives a compaction event — when it happens, the team-lead resumes by re-reading <code>todowrite</code> state and calling <code>project_state()</code>.</p><h2 id="agent-selection-guide" tabindex="-1">Agent Selection Guide <a class="header-anchor" href="#agent-selection-guide" aria-label="Permalink to &quot;Agent Selection Guide&quot;">​</a></h2><p>The team-lead selects agents based on the task domain:</p><table tabindex="0"><thead><tr><th>Task</th><th>Agent</th></tr></thead><tbody><tr><td>Explore / understand codebase</td><td><code>explore</code> (read-only, fast, safe)</td></tr><tr><td>Implement anything</td><td><code>general</code> with a descriptive persona (<code>&quot;golang-pro&quot;</code>, <code>&quot;react-frontend-engineer&quot;</code>, etc.)</td></tr><tr><td>External knowledge, docs, RFCs</td><td><code>researcher</code></td></tr><tr><td>All code review</td><td><code>review-manager</code> (never spawn reviewers directly)</td></tr><tr><td>Bug investigation</td><td><code>bug-finder</code></td></tr><tr><td>Complex / ambiguous planning</td><td><code>planning</code></td></tr><tr><td>Recurring pattern enforcement</td><td><code>harness</code></td></tr><tr><td>Post-feature maintenance</td><td><code>gardener</code></td></tr></tbody></table><p>Registered user-defined agents (<code>.md</code> files in the project&#39;s <code>agent/</code> directory) take priority over invented personas. Always check if a registered agent matches the domain before falling back to <code>general</code> + persona name.</p><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><p>The team-lead explicitly avoids these — they are failure modes, not edge cases:</p><ul><li><strong>&quot;Let me just quickly check this myself&quot;</strong> → any exploration or analysis goes to <code>explore</code>, not the team-lead directly.</li><li><strong>&quot;I&#39;ll make this one-line edit&quot;</strong> → any edit goes to the specialist, no exceptions.</li><li><strong>&quot;Let me analyze the code first&quot;</strong> → ask <code>explore</code> to analyze and report back.</li><li><strong>&quot;The agent said it&#39;s done, ship it&quot;</strong> → always review before reporting success. Trust but verify.</li><li><strong>&quot;It&#39;s a small change, skip review&quot;</strong> → small changes cause big outages. Review is proportional, not optional.</li><li><strong>&quot;I&#39;ll spawn a couple of reviewers myself&quot;</strong> → every review goes through <code>review-manager</code>. The team-lead picks the wrong reviewers, forgets to arbitrate disagreements, burns its own context on synthesis. The review-manager exists precisely to avoid this.</li><li><strong>&quot;There&#39;s a bug, let me quickly fix it&quot;</strong> → <code>bug-finder</code> first, always. Jumping straight to a fix without investigation is how workarounds and code divergence get created.</li></ul><h2 id="permissions-summary" tabindex="-1">Permissions Summary <a class="header-anchor" href="#permissions-summary" aria-label="Permalink to &quot;Permissions Summary&quot;">​</a></h2><p>The team-lead operates under a default-deny permission model:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Scope</th></tr></thead><tbody><tr><td><code>task</code></td><td>All registered agents</td></tr><tr><td><code>todowrite</code></td><td>Session task tracking</td></tr><tr><td><code>skill</code></td><td>Load skill instructions</td></tr><tr><td><code>read</code></td><td>Any file (coordination only)</td></tr><tr><td><code>question</code></td><td>Ask user for clarification</td></tr><tr><td><code>compress</code></td><td>Context window management</td></tr><tr><td>Lifecycle tools</td><td><code>project_state</code>, <code>check_artifacts</code>, <code>mark_block_done</code>, <code>complete_plan</code>, <code>register_spec</code></td></tr><tr><td><code>bash</code></td><td>Narrow git commands + basic filesystem inspection only</td></tr><tr><td><code>edit</code> / <code>write</code></td><td>Scoped to <code>docs/**</code> only (exec-plans, specs, briefs)</td></tr></tbody></table><p>All other tools (glob, grep, webfetch, etc.) are denied — those go to sub-agents.</p>',50))])}const v=i(p,[["render",u]]);export{k as __pageData,v as default};
